import subprocess
import os

def list_directory(path):
    try:
        # Check if the path exists and is a directory
        if not os.path.isdir(path):
            raise ValueError(f"The path {path} is not a valid directory.")

        # Run the 'ls -la' command and capture the output
        result = subprocess.run(['ls', '-la', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        # Check if the command was successful
        if result.returncode != 0:
            raise Exception(f"Error listing directory: {result.stderr}")

        # Return the output as a string
        return result.stdout
    except Exception as e:
        return str(e)

# Example usage:
# print(list_directory('/path/to/directory'))
