import os

def disk_usage(directory):
    try:
        # Run the 'du -sh' command and capture the output
        result = subprocess.run(['du', '-sh', directory], capture_output=True, text=True, check=True)

        # Extract the size from the output
        size = result.stdout.strip()

        # Convert the size to a human-readable format
        if size.endswith('K'):
            size = size[:-1]  # Remove 'K' for KB
        elif size.endswith('M'):
            size = size[:-1]  # Remove 'M' for MB
        elif size.endswith('G'):
            size = size[:-1]  # Remove 'G' for GB
        elif size.endswith('T'):
            size = size[:-1]  # Remove 'T' for TB
        elif size.endswith('P'):
            size = size[:-1]  # Remove 'P' for PB
        elif size.endswith('E'):
            size = size[:-1]  # Remove 'E' for EB
        else:
            size = size  # No suffix means KB by default

        return size
    except subprocess.CalledProcessError as e:
        return f"Error: {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

# Example usage:
# print(disk_usage('/path/to/directory'))
