import subprocess
import re

def disk_usage(directory):
    try:
        # Run the 'du -sh' command and capture the output
        result = subprocess.run(['du', '-sh', directory], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        # Check if the command was successful
        if result.returncode != 0:
            raise Exception(f"Error executing 'du -sh': {result.stderr.strip()}")

        # Parse the output to get the size
        output = result.stdout.strip()
        size = output.split()[0]  # Get the first part of the output which is the size

        # Convert the size to a human-readable format
        if size.endswith('K'):
            size = int(size[:-1])  # Remove 'K' and convert to int
        elif size.endswith('M'):
            size = int(size[:-1]) / 1024  # Remove 'M' and convert to int, then divide by 1024
        elif size.endswith('G'):
            size = int(size[:-1]) / (1024 * 1024)  # Remove 'G' and convert to int, then divide by 1024*1024
        else:
            size = int(size)  # Assume it's already an integer

        # Format the size as a string with 'K', 'M', or 'G' as appropriate
        if size >= 1024:
            size_str = f"{size / (1024 ** 2):.2f}G"
        elif size >= 1024:
            size_str = f"{size / 1024:.2f}M"
        else:
            size_str = f"{size}K"

        return size_str
    except Exception as e:
        return str(e)

