        return;
    }

    // Write the log entry into the buffer
    snprintf(out, out_len, "[%s] %s", level, message);
}

int main() {
    char log_buffer[100];
    format_log_entry(log_buffer, sizeof(log_buffer), "INFO", "This is a log message.");
    printf("%s", log_buffer);
    return 0;
