import base64
import uuid
from urllib.parse import quote

def encode_token(data):
    def recursive_encode(item):
        if isinstance(item, str):
            return quote(item)
        elif isinstance(item, dict):
            return {k: recursive_encode(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [recursive_encode(i) for i in item]
        else:
            raise TypeError("Unsupported data type")

    encoded_data = recursive_encode(data)
    token = base64.urlsafe_b64encode(str(encoded_data).encode()).decode()
    return token

def decode_token(token):
    def recursive_decode(item):
        if isinstance(item, str):
            try:
                decoded_item = base64.urlsafe_b64decode(quote(item)).decode()
                return eval(decoded_item)
            except Exception as e:
                return item
        elif isinstance(item, dict):
            return {k: recursive_decode(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [recursive_decode(i) for i in item]
        else:
            return item

    decoded_data = recursive_decode(eval(token))
    return decoded_data
