from urllib.parse import quote, unquote
from json import dumps, loads

def encode_token(data):
    def _encode(obj):
        if isinstance(obj, str):
            return quote(obj)
        elif isinstance(obj, bool):
            return str(obj).lower()
        elif isinstance(obj, (int, float)):
            return str(obj)
        elif isinstance(obj, list):
            return [_encode(item) for item in obj]
        elif isinstance(obj, dict):
            return {key: _encode(value) for key, value in obj.items()}
        else:
            raise TypeError(f"Type {type(obj)} not serializable")

    encoded_data = _encode(data)
    token = base64.urlsafe_b64encode(dumps(encoded_data).encode()).decode()
    return str(uuid.uuid4()) + ':' + token

def decode_token(token):
    try:
        parts = token.split(':')
        if len(parts) != 2:
            raise ValueError("Invalid token format")

        token_id, encoded_data = parts
        decoded_data = loads(base64.urlsafe_b64decode(encoded_data).decode())
        return decoded_data
    except Exception as e:
        raise ValueError(f"Failed to decode token: {e}")

