import base64
import urllib.parse

def encode_token(data):
    def _serialize(obj):
        if isinstance(obj, str):
            return obj
        elif isinstance(obj, (int, float)):
            return str(obj)
        elif isinstance(obj, bool):
            return 'true' if obj else 'false'
        elif isinstance(obj, list):
            return ','.join(_serialize(item) for item in obj)
        elif isinstance(obj, dict):
            return ';'.join(f"{k}={_serialize(v)}" for k, v in obj.items())
        else:
            raise TypeError(f"Type {type(obj)} not serializable")

    serialized_data = _serialize(data)
    encoded_data = base64.urlsafe_b64encode(serialized_data.encode()).decode()
    return encoded_data

def decode_token(token):
    decoded_data = base64.urlsafe_b64decode(token).decode()
    serialized_data = decoded_data
    deserialized_data = {}

    def _deserialize(obj):
        if isinstance(obj, str):
            return obj
        elif isinstance(obj, str):
            try:
                int_val = int(obj)
                return int_val
            except ValueError:
                return obj
        elif isinstance(obj, list):
            items = obj.split(',')
            return [_deserialize(item) for item in items]
        elif isinstance(obj, dict):
            items = obj.split(';')
            deserialized_data = {}
            for item in items:
                key, value = item.split('=')
                deserialized_data[key] = _deserialize(value)
            return deserialized_data
        else:
            raise TypeError(f"Type {type(obj)} not deserializable")

    deserialized_data = _deserialize(serialized_data)
    return deserialized_data
