import os
import json

CACHE_DIR = './cache/'

def cache_put(key, value):
    """Stores value under the string key in the file-based cache."""
    if not os.path.exists(CACHE_DIR):
        os.makedirs(CACHE_DIR)

    cache_key_path = os.path.join(CACHE_DIR, f'{key}.json')
    try:
        with open(cache_key_path, 'w') as cache_file:
            json.dump({key: value}, cache_file)
    except IOError as e:
        print(f"Failed to store in cache: {e}")

def cache_get(key):
    """Returns the stored value for the given key, or None if not found."""
    cache_key_path = os.path.join(CACHE_DIR, f'{key}.json')
    try:
        if os.path.exists(cache_key_path):
            with open(cache_key_path, 'r') as cache_file:
                data = json.load(cache_file)
                return data.get(key)
        else:
            return None
    except IOError as e:
        print(f"Failed to retrieve from cache: {e}")
        return None

