from flask import Flask, request, send_file, abort
import os
import io

app = Flask(__name__)

def get_last_lines_of_file(file_path, lines=10):
    if not os.path.isfile(file_path):
        return None

    with open(file_path, 'rb') as f:
        f.seek(0, os.SEEK_END)  # Move to the end of the file
        f.seek(max(-lines * 1024, -1024 * 5), os.SEEK_END)  # Move to the start of the last 10 lines
        buffer = bytearray()
        while f.tell() < -1024 and len(buffer) < 1024:
            buffer.extend(f.read(1024))
        lines_read = []
        while len(lines_read) < lines:
            if not buffer:
                f.seek(-1024, os.SEEK_CUR)  # Move back to read the next line
                buffer = bytearray()
            line_end = buffer.rfind(b'\n')
            if line_end == -1:
                break  # No more lines to read
            lines_read.append(buffer[:line_end].decode('utf-8'))
            buffer = buffer[line_end + 1:]  # Remove the read line
        return lines_read

@app.route('/logs')
def logs():
    file = request.args.get('file')
    file_path = os.path.join('./logs', file)

    if not os.path.isfile(file_path):
        abort(404)

    last_lines = get_last_lines_of_file(file_path)
    if last_lines is None:
        abort(404)

    return '\n'.join(last_lines)

if __name__ == '__main__':
    app.run(debug=True)
```

