import base64
import urllib.parse

def encode_token(data):
    if isinstance(data, dict):
        encoded = {key: encode_token(value) for key, value in data.items()}
        encoded_str = str(encoded)
        encoded_bytes = encoded_str.encode('utf-8')
        encoded_token = base64.urlsafe_b64encode(encoded_bytes).decode('utf-8')
        return encoded_token
    elif isinstance(data, str):
        encoded_bytes = data.encode('utf-8')
        encoded_token = base64.urlsafe_b64encode(encoded_bytes).decode('utf-8')
        return encoded_token
    else:
        return str(data)

def decode_token(token):
    token_bytes = base64.urlsafe_b64decode(token.encode('utf-8'))
    token_str = token_bytes.decode('utf-8')
    decoded_data = urllib.parse.loads(token_str)
    if isinstance(decoded_data, dict):
        decoded_dict = {}
        for key, value in decoded_data.items():
            decoded_dict[key] = decode_token(value)
        return decoded_dict
    else:
        return decoded_data
