    // Copy the message into the output buffer
    strncpy(out, message, message_len);
    out += message_len; // Move the output buffer pointer

    // Add the closing bracket and newline
    out[out_len - 1] = '\n'; // Ensure we don't exceed the buffer length
    out[out_len - 1] = ']'; // Add the closing bracket
