import subprocess
import os

def disk_usage(directory):
    if not os.path.isdir(directory):
        raise ValueError(f"{directory} is not a valid directory.")

    try:
        result = subprocess.run(['du', '-sh', directory], capture_output=True, text=True, check=True)
        output = result.stdout.strip()
        # Convert the size to a more human-readable format
        if output[-1] == 'K':
            size = float(output[:-1])
            if size < 1024:
                return f"{size}K"
            elif size < 1024 * 1024:
                return f"{size / 1024:.0f}M"
            else:
                return f"{size / (1024 * 1024):.0f}G"
        elif output[-1] == 'M':
            size = float(output[:-1])
            if size < 1024:
                return f"{size}M"
            else:
                return f"{size / 1024:.0f}G"
        else:
            return output
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to execute 'du': {e}")

# Example usage:
# print(disk_usage('/path/to/directory'))
