import base64
import uuid
from urllib.parse import quote, unquote

def encode_token(data):
    def _dict_to_base64(data):
        if isinstance(data, dict):
            items = []
            for key, value in sorted(data.items()):
                items.append(f"{key}={_dict_to_base64(value)}")
            return "&".join(items)
        elif isinstance(data, list):
            items = [_dict_to_base64(item) for item in data]
            return "[" + ",".join(items) + "]"
        else:
            return str(data)

    encoded_data = _dict_to_base64(data)
    encoded_token = base64.urlsafe_b64encode(encoded_data.encode()).decode()
    return str(uuid.uuid4()) + "." + encoded_token

def decode_token(token):
    try:
        parts = token.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid token format")

        token_id, encoded_data = parts
        decoded_data = base64.urlsafe_b64decode(encoded_data).decode()
        data_dict = _base64_to_dict(decoded_data)

        return data_dict
    except Exception as e:
        return str(e)

def _dict_to_base64(data):
    if isinstance(data, dict):
        items = []
        for key, value in sorted(data.items()):
            items.append(f"{key}={_dict_to_base64(value)}")
        return "&".join(items)
    elif isinstance(data, list):
        items = [_dict_to_base64(item) for item in data]
        return "[" + ",".join(items) + "]"
    else:
        return str(data)

def _base64_to_dict(encoded_str):
    decoded_data = base64.urlsafe_b64decode(encoded_str).decode()
    data = {}
    pairs = decoded_data.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            if value.startswith('[') and value.endswith(']'):
                data[key] = _dict_to_dict(value[1:-1])
            else:
                data[key] = _base64_to_value(value)

    return data

def _base64_to_value(value):
    decoded_value = base64.urlsafe_b64decode(value).decode()
    if decoded_value.isdigit():
        return int(decoded_value)
    try:
        if '.' in decoded_value:
            return float(decoded_value)
        return decoded_value
    except ValueError:
        if decoded_value.lower() in ('true', 'false'):
            return decoded_value.lower() == 'true'
        return decoded_value

def _dict_to_dict(data):
    if isinstance(data, dict):
        return {k: _dict_to_dict(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [_dict_to_dict(item) for item in data]
    return data
