import socket
import struct

def serialize_message(msg):
    """Convert a dictionary `msg` into bytes for sending over a TCP socket."""
    def serialize(obj):
        if isinstance(obj, dict):
            return b'dict' + b''.join(serialize(k) + serialize(v) for k, v in sorted(obj.items()))
        elif isinstance(obj, list):
            return b'list' + b''.join(serialize(x) for x in obj)
        elif isinstance(obj, str):
            return str(obj).encode('utf-8')
        elif isinstance(obj, bool):
            return b'true' if obj else b'false'
        elif isinstance(obj, (int, float)):
            return str(obj).encode('utf-8')
        else:
            raise TypeError(f"Unsupported type: {type(obj)}")

    return serialize(msg)

def deserialize_message(raw):
    """Convert received bytes back into a dictionary `msg`."""
    def deserialize(data):
        if data.startswith(b'dict'):
            return {deserialize(k): deserialize(v) for k, v in zip(data[len(b'dict'):].split(b','), data[len(b'dict'):].split(b',', 1))}
        elif data.startswith(b'list'):
            return [deserialize(x) for x in data[len(b'list'):]]
        elif data in (b'true', b'false'):
            return data == b'true'
        else:
            return data.decode('utf-8')

    return deserialize(raw)

# Example usage
if __name__ == "__main__":
    # Create a socket and connect to a server
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_address = ('localhost', 12345)
    server_socket.connect(server_address)

    # Example message
    message = {
        "name": "Alice",
        "age": 30,
        "is_student": False,
        "courses": ["Math", "Science"],
        "address": {
            "city": "Wonderland",
            "zipcode": 12345
        }
    }

    # Serialize the message
    serialized = serialize_message(message)

    # Send the message
    server_socket.sendall(serialized)

    # Receive a response from the server
    received_data = server_socket.recv(1024)

    # Deserialize the received message
    received_message = deserialize_message(received_data)

    print("Received message:", received_message)

    # Clean up the socket
    server_socket.close()
