def get_s3_client():
    try:
        # Initialize a boto3 client for S3
        s3_client = boto3.client('s3', region_name='us-east-1')

        # Function to list objects in a bucket
        def list_objects(bucket_name):
            try:
                response = s3_client.list_objects_v2(Bucket=bucket_name)
                return response.get('Contents', [])
            except NoCredentialsError:
                print("Credentials not available")
                return []

        # Function to download an object from a bucket
        def download_object(bucket_name, object_name, download_path):
            try:
                s3_client.download_file(bucket_name, object_name, download_path)
            except NoCredentialsError:
                print("Credentials not available")

        # Return the client along with the helper functions
        return s3_client, list_objects, download_object

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

