void read_username(char *out, size_t out_len) {
    // Check for an overflow condition
    if (out_len == 0) {
        return;
    }

    char buffer[1024]; // Temporary buffer to hold the input
    int index = 0; // Index to track the position in the buffer

    // Read a line from standard input
    if (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        // Remove trailing newline character if present
        if (buffer[index] == '\n') {
            buffer[index] = '\0';
            index++;
        }
    }

    // Copy the buffer to the output with a size limit
    strncat(out, buffer, out_len - index - 1); // -1 for null terminator and -1 for index
    out[out_len - index - 1] = '\0'; // Ensure the output is null-terminated
}
